 boolean isolatedMemorySession,taskConsumed,rejectOutcomeChatSave;int voiceGuardSubmissions;String voiceQaMode;
 static String requestedVoiceMode(Intent i){boolean guard=i.getBooleanExtra("voiceUiTest",false);String task=i.getStringExtra("task"),selected="voice_daily".equals(task)?"daily":"voice_pcm_daily".equals(task)?"pcm":"voice_intent_guard".equals(task)?"intent":("voice_plan_guard".equals(task)||"voice_outcome_guard".equals(task)||"system_input".equals(task))?"plan":"";return guard&&!selected.isEmpty()?"conflict":guard?"guard":selected;}
